(* ═══════════════════════════════════════════════════════
   PID Controller — Structured Text

   A full PID loop with:
   - Proportional, Integral, Derivative terms
   - Anti-windup on integral
   - Manual/Auto mode switching
   - Output clamping 0..100
   - Simulated process dynamics (1st order + noise)
   ═══════════════════════════════════════════════════════ *)

VAR
    pv, sp, err, prevErr, kp, ki, kd     : REAL;
    integral, derivative, output          : REAL;
    enabled, manual                       : BOOL;
    manOut, dt                            : REAL;
END_VAR

dt := 0.1; (* 100ms cycle *)

(* --- Read inputs --- *)
enabled  := ReadBool('Lab.PLC.PID.Enabled');
manual   := ReadBool('Lab.PLC.PID.ManualMode');
sp       := Read('Lab.PLC.PID.Setpoint');
pv       := Read('Lab.PLC.PID.ProcessValue');
kp       := Read('Lab.PLC.PID.Kp');
ki       := Read('Lab.PLC.PID.Ki');
kd       := Read('Lab.PLC.PID.Kd');
integral := Read('Lab.PLC.PID.Integral');
manOut   := Read('Lab.PLC.PID.ManualOutput');

IF NOT enabled THEN
    Write('Lab.PLC.PID.Output', 0.0);
    Write('Lab.PLC.PID.Integral', 0.0);
    Write('Lab.PLC.PID.Error', 0.0);
    RETURN;
END_IF;

IF manual THEN
    (* Manual mode: output = manual setpoint *)
    output := manOut;
    IF output > 100.0 THEN output := 100.0; END_IF;
    IF output < 0.0   THEN output := 0.0; END_IF;
    Write('Lab.PLC.PID.Output', output);
    Write('Lab.PLC.PID.Integral', 0.0);
    Write('Lab.PLC.PID.Error', sp - pv);
ELSE
    (* --- PID calculation --- *)
    err := sp - pv;
    prevErr := Read('Lab.PLC.PID.Error');

    (* Proportional *)
    output := kp * err;

    (* Integral with anti-windup *)
    integral := integral + ki * err * dt;
    IF integral > 100.0 THEN integral := 100.0; END_IF;
    IF integral < -100.0 THEN integral := -100.0; END_IF;
    output := output + integral;

    (* Derivative *)
    derivative := kd * (err - prevErr) / dt;
    output := output + derivative;

    (* Clamp output *)
    IF output > 100.0 THEN output := 100.0; END_IF;
    IF output < 0.0   THEN output := 0.0; END_IF;

    Write('Lab.PLC.PID.Output', output);
    Write('Lab.PLC.PID.Integral', integral);
    Write('Lab.PLC.PID.Error', err);
END_IF;

(* --- Simulate process (1st-order with noise) --- *)
VAR
    noise : REAL;
END_VAR
noise := (RANDOM() - 0.5) * 0.4;
pv := pv + (output * 0.008 - (pv - 20.0) * 0.015) * dt + noise;
Write('Lab.PLC.PID.ProcessValue', pv);

(* ═══════════════════════════════════════════════════════
   Sequential State Machine — Structured Text

   States:
     0 = Idle       — waiting for Start command
     1 = Starting   — ramp up (3 seconds)
     2 = Running    — normal operation, simulating T & P
     3 = Stopping   — ramp down (2 seconds)
     4 = Fault      — error state, needs Reset

   Demonstrates: IF/CASE, timers, state transitions,
   simulated process values, fault injection.
   ═══════════════════════════════════════════════════════ *)

VAR
    state, cycles, fault  : DINT;
    timer, speed, temp, press : REAL;
    startCmd, stopCmd, resetCmd : BOOL;
END_VAR

(* --- Read commands --- *)
startCmd := ReadBool('Lab.PLC.StateMachine.StartCommand');
stopCmd  := ReadBool('Lab.PLC.StateMachine.StopCommand');
resetCmd := ReadBool('Lab.PLC.StateMachine.ResetCommand');
state    := ReadInt('Lab.PLC.StateMachine.State');
timer    := Read('Lab.PLC.StateMachine.StepTimer');
speed    := Read('Lab.PLC.StateMachine.Speed');
temp     := Read('Lab.PLC.StateMachine.Temperature');
press    := Read('Lab.PLC.StateMachine.Pressure');
cycles   := ReadInt('Lab.PLC.StateMachine.CycleCount');

(* --- Auto-clear commands (edge detection) --- *)
IF startCmd THEN Write('Lab.PLC.StateMachine.StartCommand', FALSE); END_IF;
IF stopCmd  THEN Write('Lab.PLC.StateMachine.StopCommand', FALSE); END_IF;
IF resetCmd THEN Write('Lab.PLC.StateMachine.ResetCommand', FALSE); END_IF;

CASE state OF
  0: (* IDLE *)
    Write('Lab.PLC.StateMachine.StateName', 'Idle');
    IF startCmd THEN
      state := 1;
      timer := 0.0;
    END_IF;

  1: (* STARTING *)
    Write('Lab.PLC.StateMachine.StateName', 'Starting');
    timer := timer + 0.2;
    (* Ramp temperature and pressure up *)
    temp := 25.0 + (timer / 3.0) * (60.0 + speed * 0.4 - 25.0);
    press := 1.0 + (timer / 3.0) * 2.5;
    IF timer >= 3.0 THEN
      state := 2;
      timer := 0.0;
    END_IF;
    IF stopCmd THEN state := 3; timer := 0.0; END_IF;

  2: (* RUNNING *)
    Write('Lab.PLC.StateMachine.StateName', 'Running');
    timer := timer + 0.2;
    (* Simulate process with oscillation *)
    temp := 60.0 + speed * 0.4 + SIN(timer * 0.5) * 3.0 + (RANDOM() - 0.5) * 1.0;
    press := 3.5 + speed * 0.02 + COS(timer * 0.3) * 0.3;
    (* Fault if temperature > 120 *)
    IF temp > 120.0 THEN
      state := 4;
      fault := 1;
      Write('Lab.PLC.StateMachine.FaultCode', 1);
    END_IF;
    IF stopCmd THEN
      state := 3;
      timer := 0.0;
      cycles := cycles + 1;
    END_IF;

  3: (* STOPPING *)
    Write('Lab.PLC.StateMachine.StateName', 'Stopping');
    timer := timer + 0.2;
    temp := temp - (timer / 2.0) * (temp - 25.0) * 0.1;
    press := press - (timer / 2.0) * (press - 1.0) * 0.1;
    IF timer >= 2.0 THEN
      state := 0;
      temp := 25.0;
      press := 1.0;
    END_IF;

  4: (* FAULT *)
    Write('Lab.PLC.StateMachine.StateName', 'FAULT');
    IF resetCmd THEN
      state := 0;
      temp := 25.0;
      press := 1.0;
      Write('Lab.PLC.StateMachine.FaultCode', 0);
    END_IF;
END_CASE;

Write('Lab.PLC.StateMachine.State', state);
Write('Lab.PLC.StateMachine.StepTimer', timer);
Write('Lab.PLC.StateMachine.Temperature', temp);
Write('Lab.PLC.StateMachine.Pressure', press);
Write('Lab.PLC.StateMachine.CycleCount', cycles);

(* ═══════════════════════════════════════════════════════
   Up/Down Counter with Preset — Structured Text

   Counts up or down on pulse edges.
   Sets Done flag when count reaches Preset.
   ═══════════════════════════════════════════════════════ *)

VAR
    count, preset : DINT;
    up, down, rst, done : BOOL;
END_VAR

up     := ReadBool('Lab.PLC.Counter.UpPulse');
down   := ReadBool('Lab.PLC.Counter.DownPulse');
rst    := ReadBool('Lab.PLC.Counter.ResetPulse');
count  := ReadInt('Lab.PLC.Counter.Count');
preset := ReadInt('Lab.PLC.Counter.Preset');

(* Clear pulse inputs after reading *)
IF up   THEN Write('Lab.PLC.Counter.UpPulse', FALSE); END_IF;
IF down THEN Write('Lab.PLC.Counter.DownPulse', FALSE); END_IF;
IF rst  THEN Write('Lab.PLC.Counter.ResetPulse', FALSE); END_IF;

IF rst THEN
    count := 0;
    Write('Lab.PLC.Counter.Done', FALSE);
    Write('Lab.PLC.Counter.Direction', 'Reset');
ELSIF up THEN
    count := count + 1;
    Write('Lab.PLC.Counter.Direction', 'Up');
ELSIF down THEN
    IF count > 0 THEN count := count - 1; END_IF;
    Write('Lab.PLC.Counter.Direction', 'Down');
END_IF;

done := count >= preset;
Write('Lab.PLC.Counter.Count', count);
Write('Lab.PLC.Counter.Done', done);

(* ═══════════════════════════════════════════════════════
   Combinational Logic Gates — Structured Text

   Demonstrates AND, OR, XOR, NOT, NAND, and
   an SR (Set/Reset) latch, all driven by inputs.
   ═══════════════════════════════════════════════════════ *)

VAR
    a, b, c, setL, resetL, latch : BOOL;
END_VAR

a := ReadBool('Lab.PLC.Logic.Input_A');
b := ReadBool('Lab.PLC.Logic.Input_B');
c := ReadBool('Lab.PLC.Logic.Input_C');
latch := ReadBool('Lab.PLC.Logic.SR_Latch');
setL := ReadBool('Lab.PLC.Logic.Set_Latch');
resetL := ReadBool('Lab.PLC.Logic.Reset_Latch');

(* Clear set/reset pulses *)
IF setL   THEN Write('Lab.PLC.Logic.Set_Latch', FALSE); END_IF;
IF resetL THEN Write('Lab.PLC.Logic.Reset_Latch', FALSE); END_IF;

Write('Lab.PLC.Logic.AND_Result',  a AND b AND c);
Write('Lab.PLC.Logic.OR_Result',   a OR b OR c);
Write('Lab.PLC.Logic.XOR_Result',  (a XOR b) XOR c);
Write('Lab.PLC.Logic.NOT_A',       NOT a);
Write('Lab.PLC.Logic.NAND_Result', NOT (a AND b AND c));

(* SR Latch: Set has priority *)
IF setL THEN
    latch := TRUE;
ELSIF resetL THEN
    latch := FALSE;
END_IF;
Write('Lab.PLC.Logic.SR_Latch', latch);

