// ═══════════════════════════════════════════════════════
// Math Function Calculator — C# Script
//
// Reads an input value and computes several mathematical
// functions in real-time, writing results to variables.
// Also maintains a running average.
// ═══════════════════════════════════════════════════════

var input = ReadDouble("Lab.Script.Math.InputValue");
var count = ReadInt("Lab.Script.Math.SampleCount");
var prevAvg = ReadDouble("Lab.Script.Math.RunningAvg");

// Compute math functions
Write("Lab.Script.Math.Squared", input * input);
Write("Lab.Script.Math.SquareRoot", input >= 0 ? Math.Sqrt(input) : 0.0);
Write("Lab.Script.Math.Sin", Math.Sin(input * Math.PI / 180.0));
Write("Lab.Script.Math.Cos", Math.Cos(input * Math.PI / 180.0));
Write("Lab.Script.Math.Log10", input > 0 ? Math.Log10(input) : 0.0);

// Running average (exponential moving average)
count++;
var alpha = 2.0 / (count + 1);
var avg = alpha * input + (1.0 - alpha) * prevAvg;
Write("Lab.Script.Math.RunningAvg", Math.Round(avg, 4));
Write("Lab.Script.Math.SampleCount", count);

// ═══════════════════════════════════════════════════════
// Signal Data Processor — C# Script
//
// Reads a simulated raw sensor signal and performs:
//   - Low-pass exponential filter
//   - Min/Max tracking
//   - Rate of change calculation
//   - Threshold-based alarm state
//   - Statistics reset
// ═══════════════════════════════════════════════════════

var raw       = ReadDouble("Lab.Script.DataProcessor.RawSensor");
var filtered  = ReadDouble("Lab.Script.DataProcessor.FilteredValue");
var minVal    = ReadDouble("Lab.Script.DataProcessor.MinValue");
var maxVal    = ReadDouble("Lab.Script.DataProcessor.MaxValue");
var highTh    = ReadDouble("Lab.Script.DataProcessor.HighThreshold");
var lowTh     = ReadDouble("Lab.Script.DataProcessor.LowThreshold");
var coeff     = ReadDouble("Lab.Script.DataProcessor.FilterCoeff");
var reset     = ReadBool("Lab.Script.DataProcessor.ResetStats");

// Reset statistics
if (reset) {
    minVal = 999999.0;
    maxVal = -999999.0;
    Write("Lab.Script.DataProcessor.ResetStats", false);
}

// Exponential low-pass filter: y[n] = alpha*x[n] + (1-alpha)*y[n-1]
var alpha = Math.Max(0.01, Math.Min(1.0, coeff));
filtered = alpha * raw + (1.0 - alpha) * filtered;

// Track min/max
if (raw < minVal) minVal = raw;
if (raw > maxVal) maxVal = raw;

// Rate of change (difference between raw and filtered)
var roc = raw - filtered;

// Alarm state
string alarmState;
if (raw > highTh)
    alarmState = "HIGH";
else if (raw < lowTh)
    alarmState = "LOW";
else
    alarmState = "Normal";

// Write outputs
Write("Lab.Script.DataProcessor.FilteredValue", Math.Round(filtered, 3));
Write("Lab.Script.DataProcessor.MinValue", Math.Round(minVal, 3));
Write("Lab.Script.DataProcessor.MaxValue", Math.Round(maxVal, 3));
Write("Lab.Script.DataProcessor.RateOfChange", Math.Round(roc, 3));
Write("Lab.Script.DataProcessor.AlarmState", alarmState);

// ═══════════════════════════════════════════════════════
// Event Watcher — C# Script (uses OnChanged callbacks)
//
// Demonstrates the OnChanged subscription API.
// Monitors the state machine and logs transitions.
// ═══════════════════════════════════════════════════════

var state = ReadInt("Lab.PLC.StateMachine.State");
var name  = (string)(Read("Lab.PLC.StateMachine.StateName") ?? "");
var temp  = ReadDouble("Lab.PLC.StateMachine.Temperature");
var press = ReadDouble("Lab.PLC.StateMachine.Pressure");
var cycles = ReadInt("Lab.PLC.StateMachine.CycleCount");

// Log periodic status
var status = $"State Machine: {name} (state={state}), T={temp:F1}C, P={press:F2}bar, cycles={cycles}";
Write("Lab.Script.Console.Scratchpad_Text", status);

