var pv = Read("Lab.PLC.PID.ProcessValue");
var sp = Read("Lab.PLC.PID.Setpoint");
var output = Read("Lab.PLC.PID.Output");
Write("Lab.Script.Console.Scratchpad_A", pv);
Write("Lab.Script.Console.Scratchpad_B", sp);
Write("Lab.Script.Console.Scratchpad_C", output);
var count = ReadInt("Lab.Script.Console.ExecutionCount");
Write("Lab.Script.Console.ExecutionCount", count + 1);
Write("Lab.Script.Console.LastResult", $"PV={pv:F1}, SP={sp:F1}, Out={output:F1}");

Write("Lab.PLC.PID.Setpoint", 75.0);
Write("Lab.PLC.PID.Kp", 1.5);
Write("Lab.PLC.PID.Ki", 0.3);
Write("Lab.PLC.PID.Kd", 0.05);
Write("Lab.PLC.PID.Enabled", true);
Write("Lab.PLC.PID.ManualMode", false);
var count = ReadInt("Lab.Script.Console.ExecutionCount");
Write("Lab.Script.Console.ExecutionCount", count + 1);
Write("Lab.Script.Console.LastResult", "PID tuned: SP=75, Kp=1.5, Ki=0.3, Kd=0.05");

Write("Lab.PLC.StateMachine.Speed", 60.0);
Write("Lab.PLC.StateMachine.StartCommand", true);
var count = ReadInt("Lab.Script.Console.ExecutionCount");
Write("Lab.Script.Console.ExecutionCount", count + 1);
Write("Lab.Script.Console.LastResult", "State machine started at speed=60");

Write("Lab.PLC.StateMachine.StopCommand", true);
var count = ReadInt("Lab.Script.Console.ExecutionCount");
Write("Lab.Script.Console.ExecutionCount", count + 1);
Write("Lab.Script.Console.LastResult", "State machine stop command sent");

int Fib(int n) => n <= 1 ? n : Fib(n-1) + Fib(n-2);
var result = Fib(10);
Write("Lab.Script.Console.Scratchpad_A", (double)result);
var count = ReadInt("Lab.Script.Console.ExecutionCount");
Write("Lab.Script.Console.ExecutionCount", count + 1);
Write("Lab.Script.Console.LastResult", $"Fibonacci(10) = {result}");

// Bulk operation: increment counter and toggle logic inputs
for (int i = 0; i < 10; i++)
    Write("Lab.PLC.Counter.UpPulse", true);

var a = ReadBool("Lab.PLC.Logic.Input_A");
var b = ReadBool("Lab.PLC.Logic.Input_B");
Write("Lab.PLC.Logic.Input_A", !a);
Write("Lab.PLC.Logic.Input_B", !b);
var count = ReadInt("Lab.Script.Console.ExecutionCount");
Write("Lab.Script.Console.ExecutionCount", count + 1);
Write("Lab.Script.Console.LastResult", $"Counter +10, A={!a}, B={!b}");

// Reset PID
Write("Lab.PLC.PID.Setpoint", 50.0);
Write("Lab.PLC.PID.Kp", 2.0);
Write("Lab.PLC.PID.Ki", 0.5);
Write("Lab.PLC.PID.Kd", 0.1);
Write("Lab.PLC.PID.Enabled", true);
Write("Lab.PLC.PID.ManualMode", false);
// Reset State Machine
Write("Lab.PLC.StateMachine.ResetCommand", true);
Write("Lab.PLC.StateMachine.Speed", 50.0);
// Reset Counter
Write("Lab.PLC.Counter.ResetPulse", true);
// Reset Logic
Write("Lab.PLC.Logic.Input_A", false);
Write("Lab.PLC.Logic.Input_B", false);
Write("Lab.PLC.Logic.Input_C", false);
// Reset Data Processor
Write("Lab.Script.DataProcessor.ResetStats", true);
Write("Lab.Script.DataProcessor.FilterCoeff", 0.3);
Write("Lab.Script.DataProcessor.HighThreshold", 80.0);
Write("Lab.Script.DataProcessor.LowThreshold", 20.0);
// Reset Scratchpad
Write("Lab.Script.Console.Scratchpad_A", 0.0);
Write("Lab.Script.Console.Scratchpad_B", 0.0);
Write("Lab.Script.Console.Scratchpad_C", 0.0);
Write("Lab.Script.Console.Scratchpad_Text", "");
Write("Lab.Script.Console.Scratchpad_Flag", false);
var count = ReadInt("Lab.Script.Console.ExecutionCount");
Write("Lab.Script.Console.ExecutionCount", count + 1);
Write("Lab.Script.Console.LastResult", "All systems reset to defaults");
